  ('tntm', 'Teatrul Național Timișoara', 'https://www.tntm.ro', 'ical', '{"url":"https://www.tntm.ro/events.ics","organizer":"Teatrul Național „Mihai Eminescu” Timișoara","categoryHints":["teatru"]}'::jsonb, true, true, 'Official iCal export (WP Events Manager) with GEO per venue. robots.txt: Allow /.'),
  ('filarmonica-banatul', 'Filarmonica Banatul Timișoara', 'https://filarmonicabanatul.ro', 'tribe', '{"baseUrl":"https://filarmonicabanatul.ro","maxPages":4,"categoryHints":["concert"]}'::jsonb, true, true, 'Official public REST API of The Events Calendar (/wp-json/tribe/events/v1). robots.txt disallows only /wp-admin/.'),
  ('teatrul-german', 'Teatrul German de Stat Timișoara', 'https://teatrulgerman.ro', 'teatrul-german', '{"url":"https://teatrulgerman.ro/ro/program/"}'::jsonb, true, true, 'Public programme page (HTML). No robots.txt restrictions. Touring dates outside 50 km are rejected by the geofence.'),
  ('iabilet', 'iaBilet.ro', 'https://www.iabilet.ro', 'jsonld', '{"listUrls":["https://www.iabilet.ro/bilete-in-timisoara/","https://www.iabilet.ro/bilete-in-timisoara/bilete-concerte/","https://www.iabilet.ro/bilete-in-timisoara/bilete-teatru/","https://www.iabilet.ro/bilete-in-timisoara/bilete-stand-up-comedy/","https://www.iabilet.ro/bilete-in-timisoara/bilete-festivaluri/","https://www.iabilet.ro/bilete-in-timisoara/bilete-pentru-copii/"],"linkPattern":"^/bilete-[a-z0-9-]+-\\d+/$","excludePattern":"-venue-\\d+/$|voucher","maxEvents":80}'::jsonb, true, true, 'Ticketing platform; schema.org Event JSON-LD on public event pages. robots.txt allows these paths (disallows /cos/, /account/ etc.). Events in other cities are rejected by the geofence. Review terms of use before commercial use.'),
  ('visit-timisoara', 'Visit Timișoara (Primăria Timișoara)', 'https://visit-timisoara.com/ro/evenimente-si-activitati/', 'visit-timisoara', '{"baseUrl":"https://visit-timisoara.com","maxPages":3,"maxFollow":40}'::jsonb, true, true, 'Official tourism portal of the City of Timișoara (OMD Timișoara / Primăria). Public WordPress REST API /wp-json/wp/v2/events-visit; robots.txt disallows only /wp-admin/. Records have no venue: it is read from the ticket page''s schema.org data or the venue registry, otherwise the event goes to review.'),
  ('zilesinopti', 'Zile și Nopți Timișoara', 'https://zilesinopti.ro/evenimente-timisoara/', 'jsonld', '{"listUrls":["https://zilesinopti.ro/evenimente-timisoara/","https://zilesinopti.ro/evenimente-timisoara-weekend/","https://zilesinopti.ro/evenimente-copii-timisoara/","https://zilesinopti.ro/junior-timisoara/","https://zilesinopti.ro/timisoara/cultura-timisoara/"],"dayListUrl":"https://zilesinopti.ro/evenimente-timisoara/?zi={date}","days":21,"linkPattern":"^/evenimente/[a-z0-9-]+/$","maxEvents":150}'::jsonb, true, true, 'City guide (Timișoara edition). Event pages publish schema.org Event JSON-LD with venue address and coordinates, one node per performance. robots.txt disallows only /wp-admin/.'),
  ('timisoreni', 'Timisoreni.ro', 'https://www.timisoreni.ro/hub/evenimente/', 'jsonld', '{"listUrls":["https://www.timisoreni.ro/hub/evenimente/"],"linkPattern":"^/despre/[a-z0-9-]+/$","excludeVenuePattern":"^Cinema City","maxEvents":40}'::jsonb, true, true, 'Local city portal. The events hub lists schema.org Events (ItemList) with venue names; detail pages give exact times. robots.txt disallows only /editeaza/, /adauga/, /oauth/.'),
  ('faber', 'FABER Timișoara', 'https://faber.ro/ro/evenimente/', 'jsonld', '{"listUrls":["https://faber.ro/ro/","https://faber.ro/ro/evenimente/"],"linkPattern":"^/ro/evenimente/[a-z0-9-]+/$","venueNamePrefix":"FABER Timișoara","maxEvents":30}'::jsonb, true, true, 'Cultural hub (former factory). Event pages publish schema.org Event JSON-LD. No robots.txt restrictions.'),
  ('iulius-town', 'Iulius Town Timișoara', 'https://iuliustown.ro/ro/evenimente', 'mall', '{"mall":"iulius","listUrl":"https://iuliustown.ro/ro/evenimente","maxEvents":40}'::jsonb, true, true, 'Public events page of the mall (free-text dates parsed deterministically; weekly series resolved from dated programme lines). robots.txt disallows only token/data query URLs. Campaigns longer than 31 days are skipped.'),
  ('shopping-city', 'Shopping City Timișoara', 'https://www.shoppingcitytm.ro/evenimente', 'mall', '{"mall":"shoppingcity","listUrl":"https://www.shoppingcitytm.ro/evenimente"}'::jsonb, true, true, 'Public events page (page data with ISO start/end). robots.txt disallows only /api/. Campaigns longer than 31 days are skipped.'),
  ('tion', 'TION', 'https://www.tion.ro', 'press', '{"feeds":["https://www.tion.ro/feed/"],"defaultLocality":"Timișoara","secondary":true,"maxArticles":25}'::jsonb, true, true, 'Local press (RSS). An article becomes an event only with one future date and an identifiable venue in its lead; ambiguous articles are skipped. Merged with events from other sources at the same place and time.'),
